18	package org.apache.hadoop.ipc.metrics;
19	
20	import org.apache.hadoop.classification.InterfaceAudience;
21	import org.apache.hadoop.metrics2.annotation.Metric;
22	import org.apache.hadoop.metrics2.annotation.Metrics;
23	import org.apache.hadoop.metrics2.lib.DefaultMetricsSystem;
24	import org.apache.hadoop.metrics2.lib.MetricsRegistry;
25	import org.apache.hadoop.metrics2.lib.MutableRatesWithAggregation;
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	
29	/**
30	 * This class is for maintaining RPC method related statistics
31	 * and publishing them through the metrics interfaces.
32	 */
33	@InterfaceAudience.Private
34	@Metrics(about="Per method RPC metrics", context="rpcdetailed")
35	public class RpcDetailedMetrics {
36	
37	  @Metric MutableRatesWithAggregation rates;
38	  @Metric MutableRatesWithAggregation deferredRpcRates;
39	
40	  static final Logger LOG = LoggerFactory.getLogger(RpcDetailedMetrics.class);
41	  final MetricsRegistry registry;
42	  final String name;
43	
44	  RpcDetailedMetrics(int port) {
45	    name = "RpcDetailedActivityForPort"+ port;
46	    registry = new MetricsRegistry("rpcdetailed")
47	        .tag("port", "RPC port", String.valueOf(port));
48	    LOG.debug(registry.info().toString());
49	  }
50	
51	  public String name() { return name; }
52	
53	  public static RpcDetailedMetrics create(int port) {
54	    RpcDetailedMetrics m = new RpcDetailedMetrics(port);
55	    return DefaultMetricsSystem.instance().register(m.name, null, m);
56	  }
57	
58	  /**
59	   * Initialize the metrics for JMX with protocol methods
60	   * @param protocol the protocol class
61	   */
62	  public void init(Class<?> protocol) {
63	    rates.init(protocol);
64	    deferredRpcRates.init(protocol, "Deferred");
65	  }
66	
67	  /**
68	   * Add an RPC processing time sample
69	   * @param rpcCallName of the RPC call
70	   * @param processingTime  the processing time
71	   */
72	  //@Override // some instrumentation interface
73	  public void addProcessingTime(String rpcCallName, long processingTime) {
74	    rates.add(rpcCallName, processingTime);
75	  }
76	
77	  public void addDeferredProcessingTime(String name, long processingTime) {
78	    deferredRpcRates.add(name, processingTime);
79	  }
80	
81	  /**
82	   * Shutdown the instrumentation for the process
83	   */
84	  //@Override // some instrumentation interface
85	  public void shutdown() {
86	    DefaultMetricsSystem.instance().unregisterSource(name);
87	  }
88	}
