19	package org.apache.hadoop.metrics2.lib;
20	
21	import org.apache.hadoop.util.Sets;
22	import java.lang.ref.WeakReference;
23	import java.lang.reflect.Method;
24	import java.util.Iterator;
25	import java.util.Map;
26	import java.util.Set;
27	import java.util.concurrent.ConcurrentHashMap;
28	import java.util.concurrent.ConcurrentLinkedDeque;
29	import java.util.concurrent.ConcurrentMap;
30	import org.apache.hadoop.classification.InterfaceAudience;
31	import org.apache.hadoop.classification.InterfaceStability;
32	import org.apache.hadoop.metrics2.MetricsRecordBuilder;
33	import org.apache.hadoop.metrics2.util.SampleStat;
34	import org.slf4j.Logger;
35	import org.slf4j.LoggerFactory;
36	
37	
38	/**
39	 * Helper class to manage a group of mutable rate metrics.
40	 *
41	 * Each thread will maintain a local rate count, and upon snapshot,
42	 * these values will be aggregated into a global rate. This class
43	 * should only be used for long running threads, as any metrics
44	 * produced between the last snapshot and the death of a thread
45	 * will be lost. This allows for significantly higher concurrency
46	 * than {@link MutableRates}. See HADOOP-24420.
47	 */
48	@InterfaceAudience.Public
49	@InterfaceStability.Evolving
50	public class MutableRatesWithAggregation extends MutableMetric {
51	  static final Logger LOG =
52	      LoggerFactory.getLogger(MutableRatesWithAggregation.class);
53	  private final Map<String, MutableRate> globalMetrics =
54	      new ConcurrentHashMap<>();
55	  private final Set<Class<?>> protocolCache = Sets.newHashSet();
56	
57	  private final ConcurrentLinkedDeque<WeakReference<ConcurrentMap<String, ThreadSafeSampleStat>>>
58	      weakReferenceQueue = new ConcurrentLinkedDeque<>();
59	  private final ThreadLocal<ConcurrentMap<String, ThreadSafeSampleStat>>
60	      threadLocalMetricsMap = new ThreadLocal<>();
61	  // prefix for metric name
62	  private String typePrefix = "";
63	
64	  /**
65	   * Initialize the registry with all the methods in a protocol
66	   * so they all show up in the first snapshot.
67	   * Convenient for JMX implementations.
68	   * @param protocol the protocol class
69	   */
70	  public void init(Class<?> protocol) {
71	    if (protocolCache.contains(protocol)) {
72	      return;
73	    }
74	    protocolCache.add(protocol);
75	    for (Method method : protocol.getDeclaredMethods()) {
76	      String name = method.getName();
77	      LOG.debug(name);
78	      addMetricIfNotExists(name);
79	    }
80	  }
81	
82	  /**
83	   * Initialize the registry with all rate names passed in.
84	   * This is an alternative to the above init function since this metric
85	   * can be used more than just for rpc name.
86	   * @param names the array of all rate names
87	   */
88	  public void init(String[] names) {
89	    for (String name : names) {
90	      addMetricIfNotExists(name);
91	    }
92	  }
93	
94	  /**
95	   * Add a rate sample for a rate metric.
96	   * @param name of the rate metric
97	   * @param elapsed time
98	   */
99	  public void add(String name, long elapsed) {
100	    ConcurrentMap<String, ThreadSafeSampleStat> localStats =
101	        threadLocalMetricsMap.get();
102	    if (localStats == null) {
103	      localStats = new ConcurrentHashMap<>();
104	      threadLocalMetricsMap.set(localStats);
105	      weakReferenceQueue.add(new WeakReference<>(localStats));
106	    }
107	    ThreadSafeSampleStat stat = localStats.get(name);
108	    if (stat == null) {
109	      stat = new ThreadSafeSampleStat();
110	      localStats.put(name, stat);
111	    }
112	    stat.add(elapsed);
113	  }
114	
115	  @Override
116	  public synchronized void snapshot(MetricsRecordBuilder rb, boolean all) {
117	    Iterator<WeakReference<ConcurrentMap<String, ThreadSafeSampleStat>>> iter =
118	        weakReferenceQueue.iterator();
119	    while (iter.hasNext()) {
120	      ConcurrentMap<String, ThreadSafeSampleStat> map = iter.next().get();
121	      if (map == null) {
122	        // Thread has died; clean up its state
123	        iter.remove();
124	      } else {
125	        aggregateLocalStatesToGlobalMetrics(map);
126	      }
127	    }
128	    for (MutableRate globalMetric : globalMetrics.values()) {
129	      globalMetric.snapshot(rb, all);
130	    }
131	  }
132	
133	  /**
134	   * Collects states maintained in {@link ThreadLocal}, if any.
135	   */
136	  synchronized void collectThreadLocalStates() {
137	    final ConcurrentMap<String, ThreadSafeSampleStat> localStats =
138	        threadLocalMetricsMap.get();
139	    if (localStats != null) {
140	      aggregateLocalStatesToGlobalMetrics(localStats);
141	    }
142	  }
143	
144	  /**
145	   * Aggregates the thread's local samples into the global metrics. The caller
146	   * should ensure its thread safety.
147	   */
148	  private void aggregateLocalStatesToGlobalMetrics(
149	      final ConcurrentMap<String, ThreadSafeSampleStat> localStats) {
150	    for (Map.Entry<String, ThreadSafeSampleStat> entry : localStats
151	        .entrySet()) {
152	      String name = entry.getKey();
153	      MutableRate globalMetric = addMetricIfNotExists(name);
154	      entry.getValue().snapshotInto(globalMetric);
155	    }
156	  }
157	
158	  Map<String, MutableRate> getGlobalMetrics() {
159	    return globalMetrics;
160	  }
161	
162	  private synchronized MutableRate addMetricIfNotExists(String name) {
163	    MutableRate metric = globalMetrics.get(name);
164	    if (metric == null) {
165	      metric = new MutableRate(name + typePrefix, name + typePrefix, false);
166	      metric.setUpdateTimeStamp(true);
167	      globalMetrics.put(name, metric);
168	    }
169	    return metric;
170	  }
171	
172	  private static class ThreadSafeSampleStat {
173	
174	    private SampleStat stat = new SampleStat();
175	
176	    synchronized void add(double x) {
177	      stat.add(x);
178	    }
179	
180	    synchronized void snapshotInto(MutableRate metric) {
181	      if (stat.numSamples() > 0) {
182	        metric.add(stat.numSamples(), Math.round(stat.total()));
183	        stat.reset();
184	      }
185	    }
186	  }
187	
188	  public void init(Class<?> protocol, String prefix) {
189	    this.typePrefix = prefix;
190	    init(protocol);
191	  }
192	
193	}
